// A new Android project (Kotlin, Jetpack Compose) that builds without opening
// Android Studio. Modelled on an AGP 9 setup proven to build on this kind of
// machine: Kotlin is built into the Android Gradle plugin from 9.0, and Compose
// needs the Kotlin Compose compiler plugin. The Gradle wrapper is generated by a
// Gradle already on the PC, offline, so nothing has to be downloaded for it.

import * as cp from 'child_process';
import * as fs from 'fs';
import * as path from 'path';

export const ANDROID_VERSIONS = {
  gradle: '9.3.1',
  agp: '9.1.1',
  kotlin: '2.2.10',
  composeBom: '2024.09.00',
  coreKtx: '1.18.0',
  lifecycleRuntimeKtx: '2.10.0',
  activityCompose: '1.13.0',
  compileSdk: 36,
  minSdk: 24,
};

type AndroidVersions = typeof ANDROID_VERSIONS;

// Versions known to work with this template (AGP 9 with built-in Kotlin),
// the proven default first. PerDev picks the newest one already in the local Gradle cache,
// so a new project builds from what the PC has instead of downloading
// hundreds of MB.
const CANDIDATES: Record<string, { group: string; artifact: string; versions: string[]; key: keyof AndroidVersions }> = {
  agp: { group: 'com.android.tools.build', artifact: 'gradle', versions: ['9.1.1', '9.1.0', '9.0.1', '9.0.0'], key: 'agp' },
  composeBom: { group: 'androidx.compose', artifact: 'compose-bom', versions: ['2024.09.00', '2024.12.01', '2025.01.01', '2026.01.01', '2026.09.00'], key: 'composeBom' },
  coreKtx: { group: 'androidx.core', artifact: 'core-ktx', versions: ['1.18.0', '1.17.0', '1.16.0', '1.15.0'], key: 'coreKtx' },
  lifecycle: { group: 'androidx.lifecycle', artifact: 'lifecycle-runtime-ktx', versions: ['2.10.0', '2.9.4', '2.8.7'], key: 'lifecycleRuntimeKtx' },
  activity: { group: 'androidx.activity', artifact: 'activity-compose', versions: ['1.13.0', '1.12.4', '1.11.0', '1.10.1', '1.9.3'], key: 'activityCompose' },
};

export function gradleCacheDir(env: NodeJS.ProcessEnv = process.env): string {
  const home = env.GRADLE_USER_HOME || path.join(env.USERPROFILE || env.HOME || '', '.gradle');
  return path.join(home, 'caches', 'modules-2', 'files-2.1');
}

export interface AndroidChoice {
  versions: AndroidVersions;
  // Components found in the cache vs. ones that will download on the first build.
  cached: string[];
  missing: string[];
}

// Picks versions from what this PC already has (Gradle cache, SDK platforms).
export function chooseAndroidVersions(env: NodeJS.ProcessEnv = process.env): AndroidChoice {
  const cache = gradleCacheDir(env);
  const versions: AndroidVersions = { ...ANDROID_VERSIONS };
  const cached: string[] = [];
  const missing: string[] = [];
  for (const [label, c] of Object.entries(CANDIDATES)) {
    // The newest version already cached; with none cached, the proven default (first).
    const newestFirst = [...c.versions].sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
    const have = newestFirst.find((v) => fs.existsSync(path.join(cache, c.group, c.artifact, v)));
    (versions as any)[c.key] = have ?? c.versions[0];
    (have ? cached : missing).push(`${label} ${have ?? c.versions[0]}`);
  }
  const composePlugin = path.join(cache, 'org.jetbrains.kotlin.plugin.compose', 'org.jetbrains.kotlin.plugin.compose.gradle.plugin', versions.kotlin);
  (fs.existsSync(composePlugin) ? cached : missing).push(`kotlin-compose ${versions.kotlin}`);
  // core-ktx 1.17+ needs compileSdk 36; fall back to 35 only when 36 isn't installed.
  const sdk = androidSdkDir(env);
  const platforms = sdk && fs.existsSync(path.join(sdk, 'platforms')) ? fs.readdirSync(path.join(sdk, 'platforms')) : [];
  if (platforms.length && !platforms.includes('android-36') && platforms.includes('android-35')) {
    versions.compileSdk = 35;
    versions.coreKtx = '1.15.0';
  }
  return { versions, cached, missing };
}

// "Sticky Notes!" -> com.example.stickynotes
export function androidPackage(name: string): string {
  const part = name.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (!part) return 'com.example.app';
  return `com.example.${/^[a-z]/.test(part) ? part : 'app' + part}`;
}

export function androidSdkDir(env: NodeJS.ProcessEnv = process.env): string | undefined {
  const candidates = [env.ANDROID_HOME, env.ANDROID_SDK_ROOT, env.LOCALAPPDATA && path.join(env.LOCALAPPDATA, 'Android', 'Sdk')];
  return candidates.find((d): d is string => !!d && fs.existsSync(d));
}

// A Gradle already downloaded by an earlier Android build. Prefers the version
// the template uses, then the newest 9.x (AGP 9 needs Gradle 9.1 or newer).
export function findLocalGradle(env: NodeJS.ProcessEnv = process.env): { bin: string; version: string } | undefined {
  const home = env.GRADLE_USER_HOME || path.join(env.USERPROFILE || env.HOME || '', '.gradle');
  const dists = path.join(home, 'wrapper', 'dists');
  if (!fs.existsSync(dists)) return undefined;
  const exe = process.platform === 'win32' ? 'gradle.bat' : 'gradle';
  const found: { bin: string; version: string }[] = [];
  for (const d of fs.readdirSync(dists)) {
    const m = d.match(/^gradle-([\d.]+)-(bin|all)$/);
    if (!m) continue;
    for (const hash of fs.readdirSync(path.join(dists, d))) {
      const bin = path.join(dists, d, hash, `gradle-${m[1]}`, 'bin', exe);
      if (fs.existsSync(bin)) found.push({ bin, version: m[1] });
    }
  }
  const exact = found.find((f) => f.version === ANDROID_VERSIONS.gradle);
  if (exact) return exact;
  return found
    .filter((f) => Number(f.version.split('.')[0]) >= 9)
    .sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }))[0];
}

// Run in the new project's folder (in the visible setup terminal): create the
// Gradle wrapper offline with a Gradle already on the PC, then build, offline
// first; only if something is genuinely missing does it fall back to online.
export function androidSetupCommand(): string | undefined {
  const g = findLocalGradle();
  const choice = chooseAndroidVersions();
  const say = (s: string) => `echo "${s.replace(/"/g, "'")}"`;
  const steps = [
    say(`PerDev: Android build tools from this PC's cache: ${choice.cached.join(', ') || 'none'}`),
    choice.missing.length ? say(`PerDev: not cached yet (downloaded on the first build): ${choice.missing.join(', ')}`) : say('PerDev: everything needed is already cached'),
  ];
  if (!g) {
    steps.push(say('PerDev: no Gradle 9 found on this PC. Open the project once in Android Studio to create gradlew, or install Gradle 9.'));
    return steps.join(' && ');
  }
  // --offline: never download; the distribution named in the wrapper is already on disk.
  steps.push(`"${g.bin.replace(/\\/g, '/')}" wrapper --gradle-version ${g.version} --distribution-type bin --offline`);
  steps.push(say('PerDev: first build, offline first...'));
  steps.push(`(./gradlew assembleDebug --offline || (${say('PerDev: some pieces are missing; fetching only those...')} && ./gradlew assembleDebug))`);
  return steps.join(' && ');
}

// "Build me an Android app" in a folder with no Gradle project: the model alone
// writes a few loose Java/XML files that can't build. Instead PerDev lays down
// the Kotlin + Compose project (never overwriting a file) and its Gradle
// wrapper, and returns a note for the model. Undefined when nothing was done.
export function wantsAndroidApp(text: string): boolean {
  return /\bandroid\b/i.test(text) && /\b(app|application|build|make|create|develop)\b/i.test(text);
}

export async function scaffoldAndroidIfNeeded(
  root: string,
  userText: string,
  status: (text: string) => void,
): Promise<string | undefined> {
  if (!wantsAndroidApp(userText)) return undefined;
  const has = (f: string) => fs.existsSync(path.join(root, f));
  if (has('settings.gradle') || has('settings.gradle.kts')) return undefined;
  // Another kind of mobile project (React Native, Flutter) already lives here.
  if (has('package.json') || has('pubspec.yaml')) return undefined;

  status('Setting up the Android project (Kotlin + Jetpack Compose)…');
  const created: string[] = [];
  for (const [rel, content] of Object.entries(androidProjectFiles(path.basename(root)))) {
    const file = path.join(root, rel);
    if (fs.existsSync(file)) continue;
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
    created.push(rel);
  }
  const wrapper = await createGradleWrapper(root, status);
  const leftovers = findFiles(path.join(root, 'app', 'src', 'main'), /\.java$|[\\/]layout[\\/][^\\/]+\.xml$/).map((f) => path.relative(root, f).replace(/\\/g, '/'));
  return [
    'PerDev created a Kotlin + Jetpack Compose Android project here (Gradle, version catalog, MainActivity.kt with setContent):',
    created.map((f) => `- ${f}`).join('\n'),
    wrapper,
    leftovers.length
      ? `Older Java/XML files that the Compose app replaces (move what they do into Kotlin, then delete them with run_command): ${leftovers.join(', ')}`
      : '',
    'Write the app in Kotlin with Compose in app/src/main/java/.../MainActivity.kt (and more .kt files if needed), then build it and test it on the device.',
  ]
    .filter(Boolean)
    .join('\n');
}

function createGradleWrapper(root: string, status: (text: string) => void): Promise<string> {
  const isWin = process.platform === 'win32';
  if (fs.existsSync(path.join(root, isWin ? 'gradlew.bat' : 'gradlew'))) return Promise.resolve('');
  const g = findLocalGradle();
  if (!g) return Promise.resolve('No Gradle 9 was found on this PC, so there is no gradlew yet: tell the user to install Gradle 9 or open the project once in Android Studio.');
  status(`Creating the Gradle wrapper offline (Gradle ${g.version} from this PC)…`);
  return new Promise((resolve) => {
    // gradle.bat needs a shell on Windows.
    const child = cp.spawn(isWin ? `"${g.bin}"` : g.bin, ['wrapper', '--gradle-version', g.version, '--distribution-type', 'bin', '--offline'], {
      cwd: root,
      shell: isWin,
      windowsHide: true,
    });
    let err = '';
    child.stderr?.on('data', (d) => (err += d));
    child.on('error', (e) => resolve(`Creating the Gradle wrapper failed: ${e.message}`));
    child.on('close', (code) =>
      resolve(code === 0 ? 'The Gradle wrapper (gradlew) is ready; nothing was downloaded.' : `Creating the Gradle wrapper failed (exit ${code}): ${err.trim().split('\n')[0] ?? ''}`),
    );
  });
}

function findFiles(dir: string, re: RegExp, out: string[] = []): string[] {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) findFiles(p, re, out);
    else if (re.test(p)) out.push(p);
  }
  return out;
}

// For a .properties file: C:\Users\me\Sdk -> C\:\\Users\\me\\Sdk
function propertiesPath(p: string): string {
  return p.replace(/\\/g, '\\\\').replace(/:/g, '\\:');
}

export function androidProjectFiles(name: string, v: AndroidVersions = chooseAndroidVersions().versions): Record<string, string> {
  const pkg = androidPackage(name);
  const label = name.replace(/[<>&"$\\]/g, '');
  const sdk = androidSdkDir();
  const files: Record<string, string> = {
    'settings.gradle.kts': [
      'pluginManagement {',
      '    repositories {',
      '        google {',
      '            content {',
      '                includeGroupByRegex("com\\\\.android.*")',
      '                includeGroupByRegex("com\\\\.google.*")',
      '                includeGroupByRegex("androidx.*")',
      '            }',
      '        }',
      '        mavenCentral()',
      '        gradlePluginPortal()',
      '    }',
      '}',
      'dependencyResolutionManagement {',
      '    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)',
      '    repositories {',
      '        google()',
      '        mavenCentral()',
      '    }',
      '}',
      '',
      `rootProject.name = "${label}"`,
      'include(":app")',
      '',
    ].join('\n'),
    'build.gradle.kts': ['plugins {', '    alias(libs.plugins.android.application) apply false', '    alias(libs.plugins.kotlin.compose) apply false', '}', ''].join('\n'),
    'gradle.properties': ['org.gradle.jvmargs=-Xmx2048m -Dfile.encoding=UTF-8', 'android.useAndroidX=true', 'kotlin.code.style=official', ''].join('\n'),
    'gradle/libs.versions.toml': [
      '[versions]',
      `agp = "${v.agp}"`,
      `kotlin = "${v.kotlin}"`,
      `coreKtx = "${v.coreKtx}"`,
      `lifecycleRuntimeKtx = "${v.lifecycleRuntimeKtx}"`,
      `activityCompose = "${v.activityCompose}"`,
      `composeBom = "${v.composeBom}"`,
      '',
      '[libraries]',
      'androidx-core-ktx = { group = "androidx.core", name = "core-ktx", version.ref = "coreKtx" }',
      'androidx-lifecycle-runtime-ktx = { group = "androidx.lifecycle", name = "lifecycle-runtime-ktx", version.ref = "lifecycleRuntimeKtx" }',
      'androidx-activity-compose = { group = "androidx.activity", name = "activity-compose", version.ref = "activityCompose" }',
      'androidx-compose-bom = { group = "androidx.compose", name = "compose-bom", version.ref = "composeBom" }',
      'androidx-compose-ui = { group = "androidx.compose.ui", name = "ui" }',
      'androidx-compose-ui-graphics = { group = "androidx.compose.ui", name = "ui-graphics" }',
      'androidx-compose-ui-tooling = { group = "androidx.compose.ui", name = "ui-tooling" }',
      'androidx-compose-ui-tooling-preview = { group = "androidx.compose.ui", name = "ui-tooling-preview" }',
      'androidx-compose-material3 = { group = "androidx.compose.material3", name = "material3" }',
      '',
      '[plugins]',
      'android-application = { id = "com.android.application", version.ref = "agp" }',
      'kotlin-compose = { id = "org.jetbrains.kotlin.plugin.compose", version.ref = "kotlin" }',
      '',
    ].join('\n'),
    'app/build.gradle.kts': [
      'plugins {',
      '    alias(libs.plugins.android.application)',
      '    alias(libs.plugins.kotlin.compose)',
      '}',
      '',
      'android {',
      `    namespace = "${pkg}"`,
      '    compileSdk {',
      `        version = release(${v.compileSdk})`,
      '    }',
      '',
      '    defaultConfig {',
      `        applicationId = "${pkg}"`,
      `        minSdk = ${v.minSdk}`,
      `        targetSdk = ${v.compileSdk}`,
      '        versionCode = 1',
      '        versionName = "1.0"',
      '    }',
      '',
      '    buildTypes {',
      '        release {',
      '            isMinifyEnabled = false',
      '        }',
      '    }',
      '    compileOptions {',
      '        sourceCompatibility = JavaVersion.VERSION_11',
      '        targetCompatibility = JavaVersion.VERSION_11',
      '    }',
      '    buildFeatures {',
      '        compose = true',
      '    }',
      '}',
      '',
      'dependencies {',
      '    implementation(libs.androidx.core.ktx)',
      '    implementation(libs.androidx.lifecycle.runtime.ktx)',
      '    implementation(libs.androidx.activity.compose)',
      '    implementation(platform(libs.androidx.compose.bom))',
      '    implementation(libs.androidx.compose.ui)',
      '    implementation(libs.androidx.compose.ui.graphics)',
      '    implementation(libs.androidx.compose.ui.tooling.preview)',
      '    implementation(libs.androidx.compose.material3)',
      '    debugImplementation(libs.androidx.compose.ui.tooling)',
      '}',
      '',
    ].join('\n'),
    'app/src/main/AndroidManifest.xml': [
      '<?xml version="1.0" encoding="utf-8"?>',
      '<manifest xmlns:android="http://schemas.android.com/apk/res/android">',
      '',
      '    <application',
      '        android:allowBackup="true"',
      '        android:label="@string/app_name"',
      '        android:supportsRtl="true"',
      '        android:theme="@android:style/Theme.Material.Light.NoActionBar">',
      '        <activity',
      '            android:name=".MainActivity"',
      '            android:exported="true">',
      '            <intent-filter>',
      '                <action android:name="android.intent.action.MAIN" />',
      '                <category android:name="android.intent.category.LAUNCHER" />',
      '            </intent-filter>',
      '        </activity>',
      '    </application>',
      '',
      '</manifest>',
      '',
    ].join('\n'),
    'app/src/main/res/values/strings.xml': ['<resources>', `    <string name="app_name">${label}</string>`, '</resources>', ''].join('\n'),
    [`app/src/main/java/${pkg.replace(/\./g, '/')}/MainActivity.kt`]: [
      `package ${pkg}`,
      '',
      'import android.os.Bundle',
      'import androidx.activity.ComponentActivity',
      'import androidx.activity.compose.setContent',
      'import androidx.activity.enableEdgeToEdge',
      'import androidx.compose.foundation.layout.fillMaxSize',
      'import androidx.compose.foundation.layout.padding',
      'import androidx.compose.material3.MaterialTheme',
      'import androidx.compose.material3.Scaffold',
      'import androidx.compose.material3.Text',
      'import androidx.compose.runtime.Composable',
      'import androidx.compose.ui.Modifier',
      'import androidx.compose.ui.tooling.preview.Preview',
      '',
      'class MainActivity : ComponentActivity() {',
      '    override fun onCreate(savedInstanceState: Bundle?) {',
      '        super.onCreate(savedInstanceState)',
      '        enableEdgeToEdge()',
      '        setContent {',
      '            MaterialTheme {',
      '                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->',
      '                    Greeting(modifier = Modifier.padding(innerPadding))',
      '                }',
      '            }',
      '        }',
      '    }',
      '}',
      '',
      '@Composable',
      'fun Greeting(modifier: Modifier = Modifier) {',
      `    Text(text = "Hello from ${label}!", modifier = modifier)`,
      '}',
      '',
      '@Preview(showBackground = true)',
      '@Composable',
      'fun GreetingPreview() {',
      '    MaterialTheme { Greeting() }',
      '}',
      '',
    ].join('\n'),
    '.gitignore': ['*.iml', '.gradle/', '/local.properties', '.idea/', 'build/', '/captures', '.externalNativeBuild', '.cxx', ''].join('\n'),
  };
  // Where the Android SDK is: Gradle needs it to build.
  if (sdk) files['local.properties'] = `sdk.dir=${propertiesPath(sdk)}\n`;
  return files;
}
